 26→func newSearchCmd() *cobra.Command { //nolint:maintidx // command wiring is inherently complex
 27→	var (
 28→		jsonOutput       bool
 29→		codeFlag         bool
 30→		caseSensitive    bool
 31→		limitFlag        int
 32→		pageFlag         int
 33→		authorFlag       string
 34→		dateFlag         string
 35→		branchFlag       string
 36→		repoFlag         string
 37→		allReposFlag     bool
 38→		insecureHTTPAuth bool
 39→	)
 40→
 41→	cmd := &cobra.Command{
 42→		Use:   "search [query]",
 43→		Short: "Search checkpoints, commits, and sessions using semantic and keyword matching",
 44→		Long: `Search checkpoints, commits, and sessions using hybrid search (semantic + keyword),
 45→powered by the Entire search service.
 46→
 47→Requires authentication via 'entire login' (GitHub device flow).
 48→
 49→By default, results are scoped to the current repository. Use --all-repos to
 50→search across all accessible repos.
 51→
 52→Run without arguments to open an interactive search. Results are
 53→displayed in an interactive table. Use --json for machine-readable output.
 54→
 55→CLI queries also support inline filters like author:<name>, date:<week|month>,
 56→branch:<name>, repo:<owner/name>, and repo:* to search all accessible repos.`,
 57→		Args:   cobra.ArbitraryArgs,
 58→		Hidden: true,
 59→		RunE: func(cmd *cobra.Command, args []string) error {
 60→			ctx := cmd.Context()
 61→			query := strings.Join(args, " ")
 62→
 63→			if caseSensitive && !codeFlag {
 64→				return errors.New("--case-sensitive can only be used with --code")
 65→			}
 66→
 67→			if codeFlag {
 68→				// Reject flags that only apply to checkpoint search.
 69→				for _, pair := range []struct{ flag, name string }{
 70→					{authorFlag, "--author"},
 71→					{dateFlag, "--date"},
 72→					{branchFlag, "--branch"},
 73→				} {
 74→					if pair.flag != "" {
 75→						return fmt.Errorf("%s cannot be used with --code", pair.name)
 76→					}
 77→				}
 78→				if cmd.Flags().Changed("page") {
 79→					return errors.New("--page cannot be used with --code")
 80→				}
 81→
 82→				// For code search, only extract repo: inline filters from
 83→				// the query. Other checkpoint filters (author:, date:,
 84→				// branch:) are not supported and must be preserved as
 85→				// literal search text so "author:foo" searches for that
 86→				// string in code rather than being silently consumed.
 87→				codeQuery, inlineRepos := extractInlineRepoFilters(query)
 88→				var codeRepos []string
 89→				if repoFlag != "" {
 90→					codeRepos = []string{repoFlag}
 91→				}
 92→				codeRepos = append(codeRepos, inlineRepos...)
 93→				// repo:* or --all-repos means "all repos" — no filter.
 94→				// Otherwise, if no explicit filter was given, scope to the
 95→				// current repo (matching the checkpoint-search default).
 96→				hasAllRepos := allReposFlag
 97→				for _, r := range codeRepos {
 98→					if r == search.AllReposFilter {
 99→						hasAllRepos = true
100→					}
101→				}
102→				if hasAllRepos {
103→					codeRepos = nil
104→				} else {
105→					// Remove any stray "*" entries.
106→					filtered := codeRepos[:0]
107→					for _, r := range codeRepos {
108→						if r != search.AllReposFilter {
109→							filtered = append(filtered, r)
110→						}
111→					}
112→					codeRepos = filtered
113→
114→					// No explicit repo filter → derive from git origin remote.
115→					// Use forge-prefixed slug so et/ forge repos match the index.
116→					if len(codeRepos) == 0 {
117→						slug := currentRepoSlugWithForge(ctx)
118→						if slug == "" {
119→							return errors.New("could not determine current repository for code search (use --repo or --all-repos)")
120→						}
121→						codeRepos = []string{slug}
122→					}
123→				}
124→				return runCodeSearch(ctx, cmd, codeSearchOpts{
125→					query:         codeQuery,
126→					repoFilters:   codeRepos,
127→					limit:         limitFlag,
128→					caseSensitive: caseSensitive,
129→					jsonOutput:    jsonOutput,
130→					insecureHTTP:  insecureHTTPAuth,
131→				})
132→			}
133→
134→			// Extract inline filters (author:, date:, branch:, repo:) from query args.
135→			// Keep the raw query for code search (which preserves author:/date:/branch:
136→			// as literal text via extractInlineRepoFilters).
137→			rawQuery := query
138→			parsed := search.ParseSearchInput(query)
139→			query = parsed.Query
140→			if authorFlag == "" {
141→				authorFlag = parsed.Author
142→			}
143→			if dateFlag == "" {
144→				dateFlag = parsed.Date
145→			}
146→			if branchFlag == "" {
147→				branchFlag = parsed.Branch
148→			}
149→			repos := parsed.Repos
150→			if repoFlag != "" {
151→				repos = []string{repoFlag}
152→			}
153→			if err := search.ValidateRepoFilters(repos); err != nil {
154→				return fmt.Errorf("validating repo filter: %w", err)
155→			}
156→
157→			// Check for repo:* in inline filters
158→			allRepos := allReposFlag
159→			if len(repos) == 1 && repos[0] == search.AllReposFilter {
160→				allRepos = true
161→			}
162→
163→			w := cmd.OutOrStdout()
164→			isTerminal := interactive.IsTerminalWriter(w)
165→			// Mirror search.Config.HasFilters (incl. --all-repos) so an empty
166→			// query with only filters isn't rejected here. This guard runs
167→			// before git/auth, so it can't call searchCfg.HasFilters() directly.
168→			hasFilters := authorFlag != "" || dateFlag != "" || branchFlag != "" || len(repos) > 0 || allRepos
169→
170→			// Fast-fail: no query + non-interactive mode = error (before auth/git checks)
171→			if query == "" && !hasFilters && (jsonOutput || !isTerminal || IsAccessibleMode()) {
172→				return errors.New("query required when using --json, accessible mode, or piped output. Usage: entire search <query>")
173→			}
174→
175→			// Get the repo's GitHub remote URL
176→			repo, err := strategy.OpenRepository(ctx)
177→			if err != nil {
178→				cmd.SilenceUsage = true
179→				fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Run this command from within a git repository.")
180→				return NewSilentError(err)
181→			}
182→			defer repo.Close()
183→
184→			remote, err := repo.Remote("origin")
185→			if err != nil {
186→				return fmt.Errorf("could not find 'origin' remote: %w", err)
187→			}
188→			urls := remote.Config().URLs
189→			if len(urls) == 0 {
190→				return errors.New("origin remote has no URLs configured")
191→			}
192→
193→			owner, repoName, err := search.ParseGitHubRemote(urls[0])
194→			if err != nil {
195→				return fmt.Errorf("parsing remote URL: %w", err)
196→			}
197→
198→			serviceURL := os.Getenv("ENTIRE_SEARCH_URL")
199→			if serviceURL == "" {
200→				// Search lives on the data API host. Fall back to
201→				// api.BaseURL() so ENTIRE_API_BASE_URL applies; the search
202→				// package's DefaultServiceURL is only consulted by callers
203→				// that bypass this entry point.
204→				serviceURL = api.BaseURL()
205→			}
206→
207→			ghToken, err := resolveSearchToken(ctx, serviceURL, insecureHTTPAuth)
208→			if err != nil {
209→				return err
210→			}
211→
212→			searchCfg := search.Config{
213→				ServiceURL:  serviceURL,
214→				GitHubToken: ghToken,
215→				Owner:       owner,
216→				Repo:        repoName,
217→				Repos:       repos,
218→				AllRepos:    allRepos,
219→				Query:       query,
220→				Limit:       limitFlag,
221→				Page:        pageFlag,
222→				Author:      authorFlag,
223→				Date:        dateFlag,
224→				Branch:      branchFlag,
225→			}
226→
227→			// Use wildcard query when only filters are provided
228→			if query == "" && searchCfg.HasFilters() {
229→				searchCfg.Query = search.WildcardQuery
230→			}
231→
232→			// No query provided + interactive = open TUI with search bar focused
233→			if query == "" && !searchCfg.HasFilters() {
234→				searchCfg.Limit = search.DefaultLimit
235→				styles := newStatusStyles(w)
236→				model := newSearchModel(nil, "", 0, searchCfg, styles, buildCodeSearchOpts(ctx, owner, repoName, nil, false, insecureHTTPAuth))
237→				model.mode = modeSearch
238→				model.input.Focus()
239→				model.codeLoading = false // don't fetch until a query is entered
240→				p := tea.NewProgram(model)
241→				if _, err := p.Run(); err != nil {
242→					return fmt.Errorf("TUI error: %w", err)
243→				}
244→				return nil
245→			}
246→
247→			// Fetch a full page (DefaultLimit, matching the web UI) up front and
248→			// paginate client-side for all output modes; the requested --limit
249→			// only controls the client-side page size.
250→			requestedLimit := searchCfg.Limit
251→			requestedPage := searchCfg.Page
252→			searchCfg.Limit = search.DefaultLimit
253→			searchCfg.Page = 0 // let API default to page 1
254→
255→			resp, err := search.Search(ctx, searchCfg)
256→			if err != nil {
257→				return fmt.Errorf("search failed: %w", err)
258→			}
259→
260→			// JSON output: explicit flag or piped/redirected stdout
261→			if jsonOutput || !isTerminal {
262→				return writeSearchJSON(w, resp, requestedLimit, requestedPage)
263→			}
264→
265→			styles := newStatusStyles(w)
266→
267→			// Accessible mode: static table
268→			if IsAccessibleMode() {
269→				if len(resp.Results) == 0 {
270→					fmt.Fprintln(w, "No results found.")
271→					return nil
272→				}
273→				renderSearchStatic(w, resp.Results, query, resp.Total, styles)
274→				return nil
275→			}
276→
277→			// Interactive TUI
278→			codeOpts := buildCodeSearchOpts(ctx, owner, repoName, repos, allRepos, insecureHTTPAuth)
279→			if codeOpts != nil {
280→				// Use extractInlineRepoFilters on the raw query so author:/date:/branch:
281→				// tokens are preserved as literal code-search text, matching --code and
282→				// the TUI submit path. Inline repo: filters override the flag-based
283→				// scope, consistent with TUI re-search behavior.
284→				codeQuery, inlineRepos := extractInlineRepoFilters(rawQuery)
285→				codeOpts.query = codeQuery // empty → no initial code search (gated in newSearchModel)
286→				if len(inlineRepos) > 0 {
287→					if hasAllReposFilter(inlineRepos) {
288→						codeOpts.repoFilters = nil
289→					} else {
290→						codeOpts.repoFilters = inlineRepos
291→					}
292→				}
293→			}
294→			model := newSearchModel(resp.Results, query, resp.Total, searchCfg, styles, codeOpts)
295→			p := tea.NewProgram(model)
296→			if _, err := p.Run(); err != nil {
297→				return fmt.Errorf("TUI error: %w", err)
298→			}
299→			return nil
300→		},
301→	}
302→
303→	cmd.Flags().BoolVar(&jsonOutput, "json", false, "Output as JSON")
304→	cmd.Flags().BoolVar(&codeFlag, "code", false, "Search code content across repositories")
305→	cmd.Flags().BoolVar(&caseSensitive, "case-sensitive", false, "Case-sensitive code search (only with --code)")
306→	cmd.Flags().IntVar(&limitFlag, "limit", resultsPerPage, "Maximum number of results (per page for checkpoint search, total for --code)")
307→	cmd.Flags().IntVar(&pageFlag, "page", 1, "Page number (1-based)")
308→	cmd.Flags().StringVar(&authorFlag, "author", "", "Filter by author name")
309→	cmd.Flags().StringVar(&dateFlag, "date", "", "Filter by time period (week or month)")
310→	cmd.Flags().StringVar(&branchFlag, "branch", "", "Filter by branch name")
311→	cmd.Flags().StringVar(&repoFlag, "repo", "", "Filter by repository (gh/owner/repo, et/proj/repo, owner/repo, ULID, or *)")
312→	cmd.Flags().BoolVar(&allReposFlag, "all-repos", false, "Search all accessible repos instead of just the current one")
313→	addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
314→
315→	cmd.RegisterFlagCompletionFunc("date", func(*cobra.Command, []string, string) ([]string, cobra.ShellCompDirective) { //nolint:errcheck,gosec // only fails if the flag isn't defined; defined directly above
316→		return []string{"week", "month"}, cobra.ShellCompDirectiveNoFileComp
317→	})
318→	cmd.RegisterFlagCompletionFunc("repo", completeRepoFlag) //nolint:errcheck,gosec // only fails if the flag isn't defined; defined directly above
319→
320→	return cmd
321→}
