323→// resolveSearchToken returns a bearer scoped to the search service host.
324→// In split-host deployments this triggers an RFC 8693 exchange so the bearer
325→// carries the data-API audience rather than the auth-host one; single-host
326→// setups hit the same-host shortcut and return the core token unchanged.
327→// insecureHTTPAuth opts into non-loopback http:// resources at the
328→// tokenmanager layer, matching the per-command --insecure-http-auth pattern
329→// used by NewAuthenticatedAPIClient and newRecapClient.
330→func resolveSearchToken(ctx context.Context, serviceURL string, insecureHTTPAuth bool) (string, error) {
331→	if insecureHTTPAuth {
332→		auth.EnableInsecureHTTP()
333→	}
334→	token, err := auth.ResolveDataAPIToken(ctx, serviceURL)
335→	if errors.Is(err, auth.ErrNotLoggedIn) {
336→		return "", errors.New("not authenticated. Run 'entire login' to authenticate")
337→	}
338→	if err != nil {
339→		return "", fmt.Errorf("reading credentials: %w", err)
340→	}
341→	return token, nil
342→}
343→
344→// completeRepoFlag returns shell-completion suggestions for the search
345→// command's --repo flag. "*" is always offered so the wildcard works
346→// regardless of auth state. Errors are swallowed (rather than surfaced via
347→// ShellCompDirectiveError) because completion runs on every TAB press and
348→// must never pollute the user's prompt with error output.
349→func completeRepoFlag(cmd *cobra.Command, _ []string, _ string) ([]string, cobra.ShellCompDirective) {
350→	suggestions := []string{"*"}
351→	client, err := NewAuthenticatedAPIClient(cmd.Context(), false)
352→	if err != nil {
353→		return suggestions, cobra.ShellCompDirectiveNoFileComp
354→	}
355→	repos, err := client.ListRepositories(cmd.Context(), api.RepositorySortRecent)
356→	if err != nil {
357→		return suggestions, cobra.ShellCompDirectiveNoFileComp
358→	}
359→	for _, r := range repos {
360→		if r.CheckpointCount == 0 {
361→			continue // searching a repo with no checkpoints would always be empty
362→		}
363→		suggestions = append(suggestions, r.FullName)
364→	}
365→	return suggestions, cobra.ShellCompDirectiveNoFileComp
366→}
367→
368→// codeSearchEnabled reports whether the code search feature is gated on.
369→func codeSearchEnabled() bool {
370→	return os.Getenv("ENTIRE_CODE_SEARCH") == "1"
371→}
372→
373→type codeSearchOpts struct {
374→	query           string
375→	repoFilters     []string
376→	resolvedRepoIDs []string // ULIDs resolved from repoFilters via repo index
377→	limit           int
378→	caseSensitive   bool
379→	jsonOutput      bool
380→	insecureHTTP    bool
381→}
382→
383→// extractInlineRepoFilters extracts only repo: prefixed filters from a query
384→// string, returning the remaining query text and the list of repo values.
385→// Unlike search.ParseSearchInput, this does NOT consume author:, date:, or
386→// branch: tokens — those are checkpoint-search-only and should be treated as
387→// literal text in code search queries.
388→func extractInlineRepoFilters(query string) (remaining string, repos []string) {
389→	var kept []string
390→	for _, part := range strings.Fields(query) {
391→		if strings.HasPrefix(part, "repo:") {
392→			// Split comma-separated values (repo:a,b → [a, b]), matching
393→			// checkpoint search's parseListFilter behavior. Trim quotes so
394→			// repo:"gh/owner/repo" works like the unquoted form.
395→			for _, v := range strings.Split(part[5:], ",") {
396→				v = strings.Trim(v, `"'`)
397→				if v != "" {
398→					repos = append(repos, v)
399→				}
400→			}
401→		} else {
402→			kept = append(kept, part)
403→		}
404→	}
405→	return strings.Join(kept, " "), repos
406→}
407→
408→// hasAllReposFilter returns true if repos contains the wildcard "*" filter.
409→func hasAllReposFilter(repos []string) bool {
410→	for _, r := range repos {
411→		if r == search.AllReposFilter {
412→			return true
413→		}
414→	}
415→	return false
416→}
417→
418→// filterRepoWildcards returns repos with AllReposFilter entries removed.
419→func filterRepoWildcards(repos []string) []string {
420→	var out []string
421→	for _, r := range repos {
422→		if r != search.AllReposFilter {
423→			out = append(out, r)
424→		}
425→	}
426→	return out
427→}
428→
429→// buildCodeSearchOpts returns a *codeSearchOpts pre-populated with repo filters
430→// when ENTIRE_CODE_SEARCH=1 is set, or nil when the feature is off. It honors
431→// --repo, --all-repos, and inline repo: filters from the command line; when none
432→// are specified, it falls back to the current git origin slug.
433→func buildCodeSearchOpts(ctx context.Context, owner, repoName string, repos []string, allRepos, insecureHTTP bool) *codeSearchOpts {
434→	if !codeSearchEnabled() {
435→		return nil
436→	}
437→	var repoFilters []string
438→	switch {
439→	case allRepos:
440→		// nil repoFilters → searchAllCells searches all repos
441→	case len(repos) > 0:
442→		repoFilters = repos
443→	default:
444→		// Use forge-prefixed slug (e.g. "et/proj/repo") so Entire forge
445→		// repos match the index FullName. Falls back to owner/repo for
446→		// GitHub repos (gh/ prefix is stripped by resolveRepoFilters).
447→		if slug := currentRepoSlugWithForge(ctx); slug != "" {
448→			repoFilters = []string{slug}
449→		} else {
450→			repoFilters = []string{owner + "/" + repoName}
451→		}
452→	}
453→	return &codeSearchOpts{
454→		repoFilters:  repoFilters,
455→		limit:        search.DefaultLimit,
456→		insecureHTTP: insecureHTTP,
457→	}
458→}
459→
460→// codeSearchCellTimeout bounds each per-cell search call (token exchange + API).
461→const codeSearchCellTimeout = 30 * time.Second
462→
463→// runCodeSearch handles the --code flag path: search code content via peregrine.
464→//
465→// When a repo filter is specified, it routes to that repo's owning cell.
466→// Without a filter, it fans out across all cells that host the user's repos
467→// (mirroring the BFF's /api/v1/stream endpoint): list repos from the control
468→// plane, group by cell/jurisdiction, search each cell in parallel, merge.
469→func runCodeSearch(ctx context.Context, cmd *cobra.Command, opts codeSearchOpts) error {
470→	if !codeSearchEnabled() {
471→		return errors.New("code search is not yet available")
472→	}
473→
474→	if opts.query == "" {
475→		return errors.New("query required for code search. Usage: entire search --code <query>")
476→	}
477→
478→	w := cmd.OutOrStdout()
479→
480→	// Always fan out via searchAllCells — it fetches the repo index,
481→	// resolves slugs to ULIDs, and handles single- vs multi-jurisdiction.
482→	resp, err := searchAllCells(ctx, opts)
483→	if err != nil {
484→		return err
485→	}
486→
487→	isTerminal := interactive.IsTerminalWriter(w)
488→	if opts.jsonOutput || !isTerminal {
489→		return writeCodeSearchJSON(w, resp)
490→	}
491→
492→	writeCodeSearchText(w, resp)
493→	return nil
494→}
495→
496→// searchAllCells fans out code search across all cells that host the user's
497→// repos, using the shared cell-routing foundation (cell_fanout.go):
498→//  1. List repos from the control plane (entire-core) to discover cells
499→//  2. Resolve repo slug filters to ULIDs
500→//  3. Group by cell and resolve baseURLs via the shared helpers
501→//  4. Fan out via fanOutCells with per-cell codesearch.Search calls
502→//  5. Merge results (sorted by score, capped to limit)
503→func searchAllCells(ctx context.Context, opts codeSearchOpts) (*codesearch.SearchResponse, error) {
504→	// Step 1: Get repos index from the control plane.
505→	// coreapi.Client satisfies cellCoreClient (for resolveCellBaseURLs)
506→	// and also provides ListRepos (which cellCoreClient doesn't expose).
507→	coreClient, err := coreapi.New()
508→	if err != nil {
509→		if errors.Is(err, auth.ErrNotLoggedIn) {
510→			return nil, errors.New("not authenticated. Run 'entire login' to authenticate")
511→		}
512→		return nil, fmt.Errorf("resolving control-plane client: %w", err)
513→	}
514→
515→	reposCtx, reposCancel := context.WithTimeout(ctx, 10*time.Second)
516→	defer reposCancel()
517→
518→	repoIndex, err := coreClient.ListRepos(reposCtx)
519→	if err != nil {
520→		return nil, fmt.Errorf("listing repos for cell discovery: %w", err)
521→	}
522→
523→	if repoIndex.Truncated {
524→		logging.Warn(ctx, "repo index truncated; code search results may be incomplete")
525→	}
526→
527→	// Step 2: Resolve repo slug filters to ULIDs and narrow to matching cells.
528→	indexRepos := repoIndex.Repos
529→	if len(opts.repoFilters) > 0 {
530→		resolved, filtered := resolveRepoFilters(opts.repoFilters, repoIndex.Repos)
531→		if len(resolved) == 0 {
532→			hint := ""
533→			if repoIndex.Truncated {
534→				hint = " (repo index was truncated — the repo may exist but was not included)"
535→			}
536→			return nil, fmt.Errorf("no matching repositories found for filter %q%s", opts.repoFilters, hint)
537→		}
538→		opts.resolvedRepoIDs = resolved
539→		indexRepos = filtered
540→	}
541→
542→	// Step 3: Group repos by cell and resolve baseURLs via shared helpers.
543→	cells := groupReposByCell(indexRepos)
544→	if len(cells) == 0 {
545→		return &codesearch.SearchResponse{}, nil
546→	}
547→	resolveCellBaseURLs(ctx, coreClient, cells)
548→
549→	// Step 4: Fan out via the shared fanOutCells helper.
550→	// Each cell gets the full limit for single-cell, or 2x for multi-cell so
551→	// the merge sees enough candidates from every region for proper global
552→	// ranking. mergeSearchResults applies the final cap.
553→	perCellLimit := opts.limit
554→	if len(cells) > 1 && perCellLimit > 0 {
555→		perCellLimit *= 2
556→	}
557→	results, err := fanOutCells(ctx, opts.insecureHTTP, codeSearchCellTimeout, cells, func(ctx context.Context, group cellGroup, client *api.Client) (*codesearch.SearchResponse, error) {
558→		var repoIDs []string
559→		if len(opts.resolvedRepoIDs) > 0 {
560→			repoIDs = group.repoIDs
561→		}
562→		req := codesearch.SearchRequest{
563→			Query:         opts.query,
564→			Repos:         repoIDs,
565→			CaseSensitive: opts.caseSensitive,
566→		}
567→		if perCellLimit > 0 {
568→			req.MaxResults = perCellLimit
569→		}
570→		return codesearch.Search(ctx, client, req)
571→	})
572→	if err != nil {
573→		if errors.Is(err, auth.ErrNotLoggedIn) {
574→			return nil, errors.New("not authenticated. Run 'entire login' to authenticate")
575→		}
576→		return nil, fmt.Errorf("code search: %w", err)
577→	}
578→
579→	return mergeSearchResults(ctx, opts.limit, results)
580→}
581→
582→// resolveRepoFilters matches user-provided filters against the repo index,
583→// returning the ULID list for peregrine and the subset of index entries whose
584→// repos matched (for cell grouping).
585→//
586→// Matching mirrors the BFF (code-search.ts lines 315-319):
587→//
588→//	slug = filter starts with "gh/" ? strip prefix : filter unchanged
589→//	match = id === filter || full_name === slug || full_name === filter
590→//
591→// Accepted filter formats:
592→//   - ULID            — matched directly on repo ID (raw filter)
593→//   - gh/owner/repo   — GitHub repo, stripped to owner/repo for FullName match
594→//   - owner/repo      — bare slug, matched on FullName directly
595→func resolveRepoFilters(filters []string, repos []coreapi.RepoIndexEntry) (repoIDs []string, matched []coreapi.RepoIndexEntry) {
596→	byName := make(map[string]coreapi.RepoIndexEntry, len(repos))
597→	byID := make(map[string]coreapi.RepoIndexEntry, len(repos))
598→	for _, r := range repos {
599→		byName[strings.ToLower(r.FullName)] = r
600→		byID[r.ID] = r
601→	}
602→	seen := make(map[string]bool) // dedup by ID
603→	for _, f := range filters {
604→		// BFF only strips gh/ prefix; other prefixes are left as-is.
605→		slug := f
606→		if strings.HasPrefix(f, "gh/") {
607→			slug = f[3:]
608→		}
609→
610→		// Match order mirrors the BFF: id === filter || full_name === slug || full_name === filter
611→		// FullName comparison is case-insensitive so casing differences between
612→		// the git remote (e.g. entireio/CLI) and the repo index (entireio/cli)
613→		// don't cause a "no matching repositories found" failure.
614→		var r coreapi.RepoIndexEntry
615→		var ok bool
616→		if r, ok = byID[f]; !ok {
617→			if r, ok = byName[strings.ToLower(slug)]; !ok {
618→				r, ok = byName[strings.ToLower(f)]
619→			}
620→		}
621→		if ok && !seen[r.ID] {
622→			repoIDs = append(repoIDs, r.ID)
623→			matched = append(matched, r)
624→			seen[r.ID] = true
625→		}
626→	}
627→	return repoIDs, matched
628→}
629→
630→// mergeSearchResults merges responses from multiple cells into one, combining
631→// results, stats, and repo_stats. Results are sorted by Score (descending) for
632→// global relevance ranking and truncated to limit. Individual cell errors are
633→// logged and skipped, but if ALL cells fail the error is surfaced.
634→func mergeSearchResults(ctx context.Context, limit int, results []cellCallResult[*codesearch.SearchResponse]) (*codesearch.SearchResponse, error) {
635→	merged := &codesearch.SearchResponse{}
636→	var lastErr error
637→	successCount := 0
638→	for _, r := range results {
639→		if r.err != nil {
640→			lastErr = r.err
641→			continue
642→		}
643→		if r.value == nil {
644→			continue
645→		}
646→		successCount++
647→		merged.Results = append(merged.Results, r.value.Results...)
648→		merged.RepoStats = append(merged.RepoStats, r.value.RepoStats...)
649→		merged.Stats.TotalMatches += r.value.Stats.TotalMatches
650→		merged.Stats.TotalFiles += r.value.Stats.TotalFiles
651→		merged.Stats.ReposSearched += r.value.Stats.ReposSearched
652→		if r.value.Stats.DurationMs > merged.Stats.DurationMs {
653→			merged.Stats.DurationMs = r.value.Stats.DurationMs // wall-clock = slowest cell
654→		}
655→		if merged.Query == "" {
656→			merged.Query = r.value.Query
657→		}
658→	}
659→
660→	if successCount == 0 && lastErr != nil {
661→		return nil, fmt.Errorf("code search failed: %w", lastErr)
662→	}
663→
664→	// Track partial failures so consumers (especially --json) can see them.
665→	var failedJurisdictions []string
666→	for _, r := range results {
667→		if r.err == nil {
668→			continue
669→		}
670→		failedJurisdictions = append(failedJurisdictions, r.group.label())
671→	}
672→	if len(failedJurisdictions) > 0 {
673→		logging.Warn(ctx, "code search partial failure; results may be incomplete",
674→			"succeeded", successCount,
675→			"total", len(results),
676→			"failed_cells", failedJurisdictions)
677→	}
678→
679→	// Sort by score descending so results are globally ranked by relevance,
680→	// not grouped by whichever cell returned first. Stable sort with a
681→	// tiebreaker keeps --json output deterministic across runs.
682→	sort.SliceStable(merged.Results, func(i, j int) bool {
683→		a, b := merged.Results[i], merged.Results[j]
684→		if a.Score != b.Score {
685→			return a.Score > b.Score
686→		}
687→		if a.Repo != b.Repo {
688→			return a.Repo < b.Repo
689→		}
690→		if a.Path != b.Path {
691→			return a.Path < b.Path
692→		}
693→		return a.Line < b.Line
694→	})
695→
696→	// Deduplicate results that may appear from overlapping cells (e.g. a repo
697→	// with empty jurisdiction searched via both home and explicit cell).
698→	seen := make(map[string]bool, len(merged.Results))
699→	deduped := merged.Results[:0]
700→	for _, r := range merged.Results {
701→		key := r.Repo + "\x00" + r.Path + "\x00" + fmt.Sprintf("%d:%d", r.Line, r.Column)
702→		if seen[key] {
703→			continue
704→		}
705→		seen[key] = true
706→		deduped = append(deduped, r)
707→	}
708→	merged.Results = deduped
709→
710→	// Deduplicate RepoStats by repo name, summing match/file counts.
711→	repoStatsMap := make(map[string]*codesearch.RepoStats, len(merged.RepoStats))
712→	var dedupedStats []codesearch.RepoStats
713→	for _, rs := range merged.RepoStats {
714→		if existing, ok := repoStatsMap[rs.Repo]; ok {
715→			existing.MatchCount += rs.MatchCount
716→			existing.FileCount += rs.FileCount
717→		} else {
718→			entry := rs // copy
719→			repoStatsMap[rs.Repo] = &entry
720→			dedupedStats = append(dedupedStats, entry)
721→		}
722→	}
723→	// Write back merged values.
724→	for i := range dedupedStats {
725→		if m, ok := repoStatsMap[dedupedStats[i].Repo]; ok {
726→			dedupedStats[i] = *m
727→		}
728→	}
729→	merged.RepoStats = dedupedStats
730→
731→	// Stats are preserved as the sum of per-cell peregrine stats — they
732→	// reflect the true totals (including zero-match repos and per-cell
733→	// truncation), not just the deduped result slice.
734→
735→	// Cap to the caller's requested limit.
736→	if limit > 0 && len(merged.Results) > limit {
737→		merged.Results = merged.Results[:limit]
738→	}
739→
740→	// Surface partial failures in the response so JSON consumers can detect them.
741→	merged.FailedJurisdictions = failedJurisdictions
742→
743→	return merged, nil
744→}
745→
746→// writeCodeSearchJSON writes code search results as JSON.
747→func writeCodeSearchJSON(w io.Writer, resp *codesearch.SearchResponse) error {
748→	out := struct {
749→		Query               string                 `json:"query"`
750→		Results             []codesearch.Result    `json:"results"`
751→		Total               int                    `json:"total"`
752→		Stats               codesearch.Stats       `json:"stats"`
753→		RepoStats           []codesearch.RepoStats `json:"repo_stats,omitempty"`
754→		FailedJurisdictions []string               `json:"failed_jurisdictions,omitempty"`
755→	}{
756→		Query:               resp.Query,
757→		Results:             resp.Results,
758→		Total:               len(resp.Results),
759→		Stats:               resp.Stats,
760→		RepoStats:           resp.RepoStats,
761→		FailedJurisdictions: resp.FailedJurisdictions,
762→	}
763→	if out.Results == nil {
764→		out.Results = []codesearch.Result{}
765→	}
766→	data, err := jsonutil.MarshalIndentWithNewline(out, "", "  ")
767→	if err != nil {
768→		return fmt.Errorf("marshaling code search results: %w", err)
769→	}
770→	fmt.Fprint(w, string(data))
771→	return nil
772→}
773→
774→// maxContextLineLen is the maximum number of characters to display for a
775→// context_line in grep-style text output. Lines longer than this are truncated
776→// with an ellipsis so that JSONL/minified files don't blow up the terminal.
777→const maxContextLineLen = 200
778→
779→// writeCodeSearchText renders code search results in grep-style format.
780→func writeCodeSearchText(w io.Writer, resp *codesearch.SearchResponse) {
781→	if len(resp.Results) == 0 {
782→		if len(resp.FailedJurisdictions) > 0 {
783→			fmt.Fprintf(w, "No code search results found (some regions failed: %s)\n",
784→				strings.Join(resp.FailedJurisdictions, ", "))
785→		} else {
786→			fmt.Fprintln(w, "No code search results found.")
787→		}
788→		return
789→	}
790→	for _, r := range resp.Results {
791→		line := r.ContextLine
792→		runes := []rune(line)
793→		if len(runes) > maxContextLineLen {
794→			line = string(runes[:maxContextLineLen]) + "…"
795→		}
796→		fmt.Fprintf(w, "%s:%s:%d: %s\n", r.Repo, r.Path, r.Line, line)
797→	}
798→	shown := len(resp.Results)
799→	if resp.Stats.TotalMatches > shown {
800→		fmt.Fprintf(w, "\nShowing %d of %d matches across %d files in %d repos (%.0fms)\n",
801→			shown, resp.Stats.TotalMatches, resp.Stats.TotalFiles, resp.Stats.ReposSearched, resp.Stats.DurationMs)
802→	} else {
803→		fmt.Fprintf(w, "\n%d matches across %d files in %d repos (%.0fms)\n",
804→			resp.Stats.TotalMatches, resp.Stats.TotalFiles, resp.Stats.ReposSearched, resp.Stats.DurationMs)
805→	}
806→	if len(resp.FailedJurisdictions) > 0 {
807→		fmt.Fprintf(w, "Warning: results may be incomplete (failed jurisdictions: %s)\n",
808→			strings.Join(resp.FailedJurisdictions, ", "))
809→	}
810→}
811→
812→// writeSearchJSON writes client-side paginated search results as JSON.
813→func writeSearchJSON(w io.Writer, resp *search.Response, limit, page int) error {
814→	if limit <= 0 {
815→		limit = resultsPerPage
816→	}
817→
818→	total := len(resp.Results)
819→	totalPages := (total + limit - 1) / limit
820→	if totalPages < 1 {
821→		totalPages = 1
822→	}
823→	if page < 1 {
824→		page = 1
825→	}
826→
827→	// Slice results for the requested page.
828→	start := (page - 1) * limit
829→	end := start + limit
830→	var pageResults []search.Result
831→	if start < total {
832→		if end > total {
833→			end = total
834→		}
835→		pageResults = resp.Results[start:end]
836→	}
837→	if pageResults == nil {
838→		pageResults = []search.Result{}
839→	}
840→
841→	out := struct {
842→		Results    []search.Result    `json:"results"`
843→		Total      int                `json:"total"`
844→		Page       int                `json:"page"`
845→		TotalPages int                `json:"total_pages"`
846→		Limit      int                `json:"limit"`
847→		Counts     *search.TypeCounts `json:"counts,omitempty"`
848→	}{
849→		Results:    pageResults,
850→		Total:      total,
851→		Page:       page,
852→		TotalPages: totalPages,
853→		Limit:      limit,
854→		Counts:     resp.Counts,
855→	}
856→	data, err := jsonutil.MarshalIndentWithNewline(out, "", "  ")
857→	if err != nil {
858→		return fmt.Errorf("marshaling results: %w", err)
859→	}
860→	fmt.Fprint(w, string(data))
861→	return nil
862→}
