 17→func TestGroupReposByCell(t *testing.T) {
 18→	t.Parallel()
 19→	repos := []coreapi.RepoIndexEntry{
 20→		{ID: "01B", Cell: "aws-us-east-2", ClusterSlug: "us-prod", Jurisdiction: "us"},
 21→		{ID: "01C", Cell: "AWS-US-EAST-2", ClusterSlug: "us-prod", Jurisdiction: "US"}, // case-folds into same group
 22→		{ID: "01A", Cell: euWestCell, ClusterSlug: "eu-prod", Jurisdiction: "eu"},
 23→		{ID: "", Cell: euWestCell}, // no ID → skipped
 24→		// Blank cell in different jurisdictions must NOT collapse into one
 25→		// group — each routes via its own jurisdiction fallback.
 26→		{ID: "01D", Jurisdiction: "eu"},
 27→		{ID: "01E", Jurisdiction: "us"},
 28→	}
 29→	cells := groupReposByCell(repos)
 30→	if len(cells) != 4 {
 31→		t.Fatalf("groups = %d, want 4: %+v", len(cells), cells)
 32→	}
 33→	// Deterministic order by cell name, jurisdiction tiebreak:
 34→	// ""/eu < ""/us < aws-eu-west-1 < aws-us-east-2.
 35→	order := []struct{ cell, jurisdiction string }{
 36→		{"", "eu"}, {"", "us"}, {euWestCell, "eu"}, {"aws-us-east-2", "us"},
 37→	}
 38→	for i, want := range order {
 39→		if cells[i].cell != want.cell || cells[i].jurisdiction != want.jurisdiction {
 40→			t.Fatalf("group[%d] = %q/%q, want %q/%q", i, cells[i].cell, cells[i].jurisdiction, want.cell, want.jurisdiction)
 41→		}
 42→	}
 43→	if got := strings.Join(cells[0].repoIDs, ","); got != "01D" {
 44→		t.Fatalf("blank-cell eu repoIDs = %q, want 01D", got)
 45→	}
 46→	us := cells[3]
 47→	if got := strings.Join(us.repoIDs, ","); got != "01B,01C" {
 48→		t.Fatalf("us repoIDs = %q, want 01B,01C", got)
 49→	}
 50→	if us.clusterSlug != "us-prod" || us.jurisdiction != "us" {
 51→		t.Fatalf("us group coordinates = %+v, want us-prod/us", us)
 52→	}
 53→}
 54→
 55→// TestResolveCellBaseURLs_RefusesBaseURLWithoutJurisdiction pins the guard: a
 56→// concrete baseURL is only usable together with the jurisdiction its token
 57→// must be minted for; a catalog row with no jurisdiction leaves the group on
 58→// home routing instead of dialing a foreign cell with a home token.
 59→func TestResolveCellBaseURLs_RefusesBaseURLWithoutJurisdiction(t *testing.T) {
 60→	t.Parallel()
 61→	cells := []cellGroup{{cell: "aws-eu-west-1", clusterSlug: "eu-prod"}} // no jurisdiction anywhere
 62→	fake := &fakeCellCore{clusters: []coreapi.Cluster{
 63→		{Slug: "eu-prod", ApiUrl: coreapi.NewOptString(euCellAPIURL)}, // row has no jurisdiction either
 64→	}}
 65→	resolveCellBaseURLs(context.Background(), fake, cells)
 66→	if cells[0].baseURL != "" || cells[0].jurisdiction != "" {
 67→		t.Fatalf("group = %+v, want untouched (home routing)", cells[0])
 68→	}
 69→}
 70→
 71→// TestResolveCellBaseURLs_JoinsOnClusterSlug pins the catalog join key: the
 72→// cluster catalog has no cell field, so groups must join on ClusterSlug —
 73→// joining the cell name against Cluster.Slug only works when the two happen to
 74→// coincide.
 75→func TestResolveCellBaseURLs_JoinsOnClusterSlug(t *testing.T) {
 76→	t.Parallel()
 77→	cells := []cellGroup{
 78→		// Slug ("eu-prod") differs from the cell name (euWestCell).
 79→		{cell: euWestCell, clusterSlug: "eu-prod", jurisdiction: "eu"},
 80→		{cell: "aws-ap-south-1", clusterSlug: "ap-prod", jurisdiction: "ap"}, // not in catalog
 81→	}
